620	  void _applyStreamEvent(
621	    String userMessageId,
622	    String aiMessageId,
623	    ChatStreamEvent event,
624	  ) {
625	    if (isClosed) {
626	      return;
627	    }
628	    final current = state;
629	    if (current is! ChatReady) {
630	      return;
631	    }
632	    switch (event) {
633	      case ChatMessageCreatedEvent(userMessageId: final serverId):
634	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
635	        // now this story's first consumer, captured onto the matching
636	        // local user bubble by id so a later `retryMessage` call (on the
637	        // AI bubble this same send produces) has a non-null `serverId` to
638	        // key `chat-messages-retry` off of.
639	        emit(
640	          current.copyWith(
641	            messages: [
642	              for (final message in current.messages)
643	                if (message.id == userMessageId)
644	                  message.copyWith(serverId: serverId)
645	                else
646	                  message,
647	            ],
648	          ),
649	        );
650	      case ChatTokenEvent(delta: final delta):
651	        emit(
652	          current.copyWith(
653	            messages: [
654	              for (final message in current.messages)
655	                if (message.id == aiMessageId)
656	                  message.copyWith(content: message.content + delta)
657	                else
658	                  message,
659	            ],
660	          ),
661	        );
662	      case ChatDoneEvent():
663	        emit(
664	          current.copyWith(
665	            messages: [
666	              for (final message in current.messages)
667	                if (message.id == aiMessageId)
668	                  message.copyWith(status: ChatMessageStatus.complete)
669	                else
670	                  message,
671	            ],
672	          ),
673	        );
674	    }
675	  }
