701	  /// spec-6-4 (RF10) — Boundaries: the bookmark affordance exists only on
702	  /// [ChatMessageRole.user] bubbles; tapping it turns that exact message
703	  /// into a journal Entry (`source: EntrySource.chat`) through
704	  /// [_saveChatMessageAsEntryUseCase] only — never `EntriesRepository`
705	  /// directly (AGENTS.md's RF10 rule). A no-op (I/O & Edge-Case Matrix)
706	  /// when: [state] isn't [ChatReady]; [messageId] isn't found; its role
707	  /// isn't [ChatMessageRole.user]; its [ChatUiMessage.serverId] is still
708	  /// `null` (mirrors [retryMessage]'s own guard — the backend id a save
709	  /// sends as `chatMessageId`, Boundaries); its [ChatUiMessage.
710	  /// bookmarkState] is already [BookmarkSaved] (client-side no-op — a
711	  /// repeat save is itself idempotent at the backend, Boundaries) or
712	  /// already [BookmarkSaving] (re-entrancy guard, scoped to this one
713	  /// message — [_isSending] stays scoped to send/retry only, never shared
714	  /// with this guard).
715	  Future<void> bookmarkMessage(String messageId) async {
716	    final current = state;
717	    if (current is! ChatReady) {
718	      return;
719	    }
720	    final index = current.messages.indexWhere(
721	      (message) => message.id == messageId,
722	    );
723	    if (index == -1) {
724	      return;
725	    }
726	    final message = current.messages[index];
727	    final serverId = message.serverId;
728	    if (message.role != ChatMessageRole.user ||
729	        serverId == null ||
730	        message.bookmarkState is BookmarkSaved ||
731	        message.bookmarkState is BookmarkSaving) {
732	      return;
733	    }
734	
735	    // Boundaries: both of this method's own emit() calls check isClosed
736	    // first — not just the one after the await below.
737	    if (isClosed) {
738	      return;
739	    }
740	    _bookmarkStateByServerId[serverId] = const BookmarkState.saving();
741	    emit(
742	      current.copyWith(
743	        messages: [
744	          for (final existing in current.messages)
745	            if (existing.id == messageId)
746	              existing.copyWith(bookmarkState: const BookmarkState.saving())
747	            else
748	              existing,
749	        ],
750	      ),
751	    );
752	
753	    final sideEffectResult = await isolatedSideEffect(
754	      () => _saveChatMessageAsEntry(
755	        content: message.content,
756	        chatMessageId: serverId,
757	      ),
758	    );
759	    // Flattens isolatedSideEffect's own outer Either (Left only on a
760	    // thrown exception, mapped to malformedResponse — I/O matrix: "Side-
761	    // effect throws") with the use case's own inner Either (Left on a
762	    // normal, non-thrown save failure — I/O matrix: "Save fails") into
763	    // one plain Either<Failure, Entry>, so both scenarios flip the bubble
764	    // to the same retryable error state via the one match() below.
765	    final result = sideEffectResult.match(
766	      (failure) => left(failure),
767	      (inner) => inner,
768	    );
769	
770	    final resolvedState = result.match(
771	      (failure) => BookmarkState.error(failure),
772	      (_) => const BookmarkState.saved(),
773	    );
774	    // Review fix (round 2) — written through to the serverId-keyed map
775	    // unconditionally (even if the live [ChatReady] below has since moved
776	    // on to a different session), so the outcome is never lost; re-
777	    // entering any session carrying this message picks it back up via
778	    // [_fromDomain].
779	    _bookmarkStateByServerId[serverId] = resolvedState;
780	
781	    if (isClosed) {
782	      return;
783	    }
784	    final latest = state;
785	    if (latest is! ChatReady) {
786	      return;
787	    }
788	    // Matched by `serverId`, not the in-session `messageId` — the latter
789	    // is stale once [switchSession]/[startNewSession] reloads this exact
790	    // session's history mid-save, which re-derives every message's own
791	    // `id` from the server (`_fromDomain`) instead of keeping the local
792	    // id this call started with.
793	    final stillVisible = latest.messages.any(
794	      (existing) => existing.serverId == serverId,
795	    );
796	    if (!stillVisible) {
797	      return;
798	    }
799	    emit(
800	      latest.copyWith(
801	        messages: [
802	          for (final existing in latest.messages)
803	            if (existing.serverId == serverId)
804	              existing.copyWith(bookmarkState: resolvedState)
805	            else
806	              existing,
807	        ],
808	      ),
809	    );
810	  }
