903	  /// Flattens [isolatedSideEffect]'s own outer `Either` (`Left` only on a
904	  /// thrown exception) with [ChatRepository.generateInsight]'s own inner
905	  /// `Either` (`Left` on a transport failure; `Right(null)` on a
906	  /// successful call whose `status` wasn't `'ready'`) into one plain
907	  /// `Either<Failure, ChatInsight?>` — same flattening shape
908	  /// [bookmarkMessage] already uses for its own side effect. Any `Left`,
909	  /// or a `null` insight either way, is a fully silent no-op (Boundaries:
910	  /// "no card, no overlay, no retry affordance"). On a real insight,
911	  /// guards [isClosed], that [requestSeq] is still the *most recently
912	  /// fired* request (review fix: discards a stale result from a request
913	  /// a later one has since superseded, so it can never overwrite a newer
914	  /// `activeInsight` or resurrect one the user already dismissed), and
915	  /// that [state] is still [ChatReady] for this exact [sessionId] — an
916	  /// insight resolving after [switchSession]/[startNewSession] moved away
917	  /// is dropped (Boundaries/I/O matrix: "Session switched mid-flight").
918	  void _applyInsightResult(
919	    String sessionId,
920	    int requestSeq,
921	    Either<Failure, Either<Failure, ChatInsight?>> result,
922	  ) {
923	    final flattened = result.match(
924	      (failure) => left(failure),
925	      (inner) => inner,
926	    );
927	    final insight = flattened.match((_) => null, (insight) => insight);
928	    if (insight == null || isClosed || requestSeq != _insightRequestSeq) {
929	      return;
930	    }
931	    final current = state;
932	    if (current is! ChatReady || current.sessionId != sessionId) {
933	      return;
934	    }
935	    emit(current.copyWith(activeInsight: insight));
936	  }
