34	  @override
35	  Future<Either<Failure, List<ChatSession>>> listSessions() async {
36	    final result = await _remoteDataSource.listSessions();
37	    return result.match(
38	      (failure) async {
39	        // `requirements.md`: "`GET /chat/sessions` — works offline
40	        // (cache)" — same cursor-null-page cache-fallback convention
41	        // `EntriesRepositoryImpl.list()` already uses; every other
42	        // `Failure` (e.g. `authExpired`) propagates as `Left`, unmapped.
43	        if (failure is NetworkOffline || failure is NetworkTimeout) {
44	          return _cachedSessions();
45	        }
46	        return left(failure);
47	      },
48	      (dtos) async {
49	        try {
50	          await _sessionsBox.putAll({
51	            for (final dto in dtos) dto.id: dto.toJson(),
52	          });
53	        } catch (error) {
54	          // A thrown Hive/disk exception must never escape unmapped
55	          // (RNF09) — same fallback `EntriesRepositoryImpl`'s own writes
56	          // already use.
57	          return left(Failure.malformedResponse(message: error.toString()));
58	        }
59	        return right(dtos.map((dto) => dto.toEntity()).toList());
60	      },
61	    );
62	  }
