162	  @override
163	  Future<Either<Failure, Unit>> clearLocalCache() async {
164	    // Review finding: the two boxes are cleared independently (each in its
165	    // own try/catch) rather than sequentially inside one shared try/catch —
166	    // otherwise a throw clearing `_sessionsBox` would skip `_messagesBox.
167	    // clear()` entirely, leaving it uncleared on logout with no record of
168	    // why. Both are always attempted; `Left` only if at least one failed.
169	    // Code-review patch: each error is tagged with which box produced it —
170	    // an untagged `firstError` would make a real disk-full failure
171	    // unattributable from logs alone.
172	    String? firstError;
173	    try {
174	      await _sessionsBox.clear();
175	    } catch (error) {
176	      firstError = 'chat_sessions: $error';
177	    }
178	    try {
179	      await _messagesBox.clear();
180	    } catch (error) {
181	      firstError ??= 'chat_messages: $error';
182	    }
183	    if (firstError != null) {
184	      // Same RNF09 rationale as every other Hive-write guard in this file.
185	      return left(Failure.malformedResponse(message: firstError));
186	    }
187	    return right(unit);
188	  }
