190	  /// [listSessions]'s own offline/timeout fallback — a full `chat_
191	  /// sessions` Hive box dump, sorted `updatedAt` desc (so `ChatCubit.
192	  /// init()`'s own "reuse the most recent session" pick is already
193	  /// correctly ordered even against the cache), same "always `Right`,
194	  /// even if empty" convention `EntriesRepositoryImpl._offlineFallback()`
195	  /// already uses. Each entry is decoded independently — one corrupt
196	  /// cached entry is skipped, never discarding every other (valid)
197	  /// session in the box over it.
198	  Either<Failure, List<ChatSession>> _cachedSessions() {
199	    final sessions = <ChatSession>[];
200	    for (final json in _sessionsBox.values) {
201	      try {
202	        sessions.add(
203	          ChatSessionDto.fromJson(Map<String, dynamic>.from(json)).toEntity(),
204	        );
205	      } catch (_) {
206	        // Skip this one corrupt entry — see doc above.
207	      }
208	    }
209	    // Review fix: `tryParse` (never `parse`) — same crash-safe pattern as
210	    // the sibling "most recent session" sorts in `ChatCubit._bootstrap`
211	    // and `_ConversasSection`; a malformed cached `updatedAt` must never
212	    // throw out of this offline-cache fallback (RNF09).
213	    sessions.sort(
214	      (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0)).compareTo(
215	        DateTime.tryParse(a.updatedAt) ?? DateTime(0),
216	      ),
217	    );
218	    return right(sessions);
219	  }
