221	  /// [listMessages]'s own offline/timeout fallback — a full `chat_
222	  /// messages` Hive box dump filtered to [sessionId] and sorted `seq`
223	  /// ascending (the backend's own "ordered by seq", `openapi.yaml`), same
224	  /// "always `Right`, even if empty" convention [_cachedSessions] above
225	  /// uses. Each entry is decoded independently, same corrupt-entry
226	  /// isolation as [_cachedSessions].
227	  Either<Failure, List<ChatMessage>> _cachedMessages(String sessionId) {
228	    final messages = <ChatMessage>[];
229	    for (final json in _messagesBox.values) {
230	      try {
231	        final message = ChatMessageDto.fromJson(Map<String, dynamic>.from(json))
232	            .toEntity();
233	        if (message.sessionId == sessionId) {
234	          messages.add(message);
235	        }
236	      } catch (_) {
237	        // Skip this one corrupt entry — see doc above.
238	      }
239	    }
240	    messages.sort((a, b) => a.seq.compareTo(b.seq));
241	    return right(messages);
242	  }
