26	  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
27	    final result = await _apiClient.get('chat-sessions-list');
28	    return result.flatMap((json) {
29	      try {
30	        final data = json['data'] as List<dynamic>;
31	        // Review fix: one malformed item is skipped rather than
32	        // discarding every other valid session in the response — same
33	        // per-item isolation the offline-cache fallback already applies.
34	        final dtos = <ChatSessionDto>[];
35	        for (final item in data) {
36	          try {
37	            dtos.add(ChatSessionDto.fromJson(item as Map<String, dynamic>));
38	          } catch (_) {
39	            // Skip this one malformed item.
40	          }
41	        }
42	        // Review fix: a non-empty response where every item failed to
43	        // decode is a parse failure, not "zero sessions" — returning
44	        // `right([])` here would make `ChatCubit._bootstrap()` believe
45	        // none exist and spuriously `createSession()`, hiding the user's
46	        // real sessions behind a new empty one.
47	        if (data.isNotEmpty && dtos.isEmpty) {
48	          return left(
49	            Failure.malformedResponse(
50	              message: 'All items in listSessions() response failed to decode',
51	            ),
52	          );
53	        }
54	        return right(dtos);
55	      } catch (error) {
