156	  /// segments, Code Map) — same SSE buffering/parsing as [sendMessage]
157	  /// above, via the shared [_consumeSse] helper; see
158	  /// `ChatRepository.retryMessage`'s own doc for the terminal-handling
159	  /// contract both share.
160	  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
161	    String sessionId,
162	    String userMessageId,
163	  ) => _consumeSse(
164	    _apiClient.postStream(
165	      'chat-messages-retry',
166	      pathParams: [sessionId, userMessageId],
167	      data: const {},
168	    ),
169	  );
