195	  /// The shared SSE-consumption step behind [sendMessage]/[retryMessage]
196	  /// (Code Map: "extract shared SSE buffer/parse helper") — buffers raw
197	  /// text from [chunks] until a full `\n\n`-terminated SSE event block is
198	  /// available, then hands each complete block to [_parseEvent].
199	  ///
200	  /// Terminal handling (Design Notes/I/O matrix):
201	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
202	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
203	  ///   forwarded as-is and ends the stream immediately — covers "Send
204	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
205	  ///   queued) and any other transport-level failure.
206	  /// - A parsed `done` event or an in-band `error` event (mapped via
207	  ///   [Failure.fromCode]) both end the stream right after being emitted
208	  ///   — the backend's own SSE ordering guarantees neither is followed by
209	  ///   anything else worth reading.
210	  /// - If the underlying byte stream simply ends (no exception, no
211	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
212	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
213	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
214	  ///   (Design Notes).
215	  Stream<Either<Failure, ChatStreamEvent>> _consumeSse(
216	    Stream<Either<Failure, String>> chunks,
217	  ) async* {
218	    var buffer = '';
219	    await for (final chunkResult in chunks) {
220	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
221	      if (upstreamFailure != null) {
222	        yield left(upstreamFailure);
223	        return;
224	      }
225	      final chunk = chunkResult.fold((_) => '', (s) => s);
226	      // Normalize after concatenation, not per-chunk — a `\r\n` line
227	      // ending split exactly across two chunks (one ends `\r`, the next
228	      // starts `\n`) would otherwise survive unnormalized in `buffer`.
229	      buffer = (buffer + chunk).replaceAll('\r\n', '\n');
230	
231	      var separatorIndex = buffer.indexOf('\n\n');
232	      while (separatorIndex != -1) {
233	        final rawEvent = buffer.substring(0, separatorIndex);
234	        buffer = buffer.substring(separatorIndex + 2);
235	        if (rawEvent.trim().isNotEmpty) {
236	          final parsed = _parseEvent(rawEvent);
237	          if (parsed != null) {
238	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
239	            final isFailure = parsed.isLeft();
240	            yield parsed;
241	            // A `done`/in-band-error exit is a clean terminal event, not
242	            // a drop — return directly, skipping the trailing
243	            // mid-stream-drop failure below.
244	            if (isDone || isFailure) {
245	              return;
246	            }
247	          }
248	        }
249	        separatorIndex = buffer.indexOf('\n\n');
250	      }
251	    }
252	    // Reached only if the byte stream ended on its own (no exception, no
253	    // `done`/`error` event ever parsed) — a mid-stream drop.
254	    yield left(
255	      const Failure.networkTimeout(
256	        message: 'Connection closed before the response completed',
257	      ),
258	    );
259	  }
260	
261	  /// Parses one complete, blank-line-delimited SSE event block into a
262	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
263	  /// when the block should simply be skipped — a `context` event
264	  /// (Boundaries: "received and discarded", never surfaced as a
265	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
266	  /// (forward-compatible: an unknown future event type is ignored rather
267	  /// than treated as malformed). Any JSON-decode failure, or a decoded
268	  /// payload missing the field a known event name requires, maps to
269	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
270	  /// parse as expected becomes `Failure.malformedResponse`, never a
271	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
272	  /// `async*` body.
273	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
274	    String? eventName;
275	    final dataLines = <String>[];
276	    for (final line in rawEvent.split('\n')) {
277	      if (line.startsWith('event:')) {
278	        eventName = line.substring('event:'.length).trim();
279	      } else if (line.startsWith('data:')) {
280	        var value = line.substring('data:'.length);
281	        if (value.startsWith(' ')) {
282	          value = value.substring(1);
283	        }
284	        dataLines.add(value);
285	      }
286	    }
287	    if (eventName == null) {
288	      return null;
289	    }
290	    final dataStr = dataLines.join('\n');
291	
292	    switch (eventName) {
293	      case 'message_created':
294	        try {
295	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
296	          return right(ChatMessageCreatedEvent(json['id'] as String));
297	        } catch (error) {
298	          return left(
299	            Failure.malformedResponse(
300	              message: 'malformed message_created event: $error',
301	            ),
302	          );
303	        }
304	      case 'context':
305	        // Boundaries: "never rendering the SSE `context` event's
306	        // retrieval/citation data" — received and discarded.
307	        return null;
308	      case 'token':
309	        try {
310	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
311	          return right(ChatTokenEvent(json['delta'] as String));
312	        } catch (error) {
313	          return left(
314	            Failure.malformedResponse(message: 'malformed token event: $error'),
315	          );
316	        }
317	      case 'done':
318	        return right(const ChatDoneEvent());
319	      case 'error':
320	        try {
321	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
322	          final code = json['code'] as String;
323	          final message = json['message'];
324	          return left(
325	            Failure.fromCode(
326	              code,
327	              message is String ? message : 'Unknown error',
328	            ),
329	          );
330	        } catch (error) {
331	          return left(
332	            Failure.malformedResponse(message: 'malformed error event: $error'),
333	          );
334	        }
335	      default:
336	        // Forward-compatible: an event name this client doesn't
337	        // recognize is skipped, not treated as malformed.
338	        return null;
339	    }
340	  }
341	}
